import * as T from 'three';
import {RoundedBoxGeometry} from 'three/addons/geometries/RoundedBoxGeometry.js';
export {makeActor,makeFood} from './character.js';
const materials=new Map();const mat=c=>{if(!materials.has(c))materials.set(c,new T.MeshStandardMaterial({color:c,roughness:1}));return materials.get(c);};
function box(p,w,h,d,c,x=0,y=0,z=0,r=.02){const m=new T.Mesh(new RoundedBoxGeometry(w,h,d,1,r),mat(c));m.position.set(x,y,z);m.receiveShadow=true;m.castShadow=h>.3;p.add(m);return m;}
function texture(draw,w=256,h=256){const c=document.createElement('canvas');c.width=w;c.height=h;draw(c.getContext('2d'),w,h);const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;return t;}
export function label(p,text,x,y,z,w=5){const tx=texture((c,W,H)=>{c.fillStyle='#ffffff';c.font='900 58px sans-serif';c.textAlign='center';c.textBaseline='middle';c.strokeStyle='#234237';c.lineWidth=7;c.strokeText(text,W/2,H/2);c.fillText(text,W/2,H/2);},512,128);const m=new T.Sprite(new T.SpriteMaterial({map:tx,depthTest:true}));m.position.set(x,y,z);m.scale.set(w,w/4,1);p.add(m);return m;}
export function makeWorld(scene){const hub=new T.Group();scene.add(hub);const turf=texture((c,w,h)=>{c.fillStyle='#80d353';c.fillRect(0,0,w,h);for(let i=0;i<450;i++){c.fillStyle=i%2?'#90dd62':'#75c84c';c.fillRect(i*71%w,i*43%h,4,3);}});turf.wrapS=turf.wrapT=T.RepeatWrapping;turf.repeat.set(12,12);const field=box(hub,38,.5,45,0x80d353,0,-.29,-2);field.material=new T.MeshStandardMaterial({map:turf,roughness:1});
 const stone=texture((c,w,h)=>{c.fillStyle='#aeb9bc';c.fillRect(0,0,w,h);for(let y=0;y<h;y+=48)for(let x=0;x<w;x+=64){c.fillStyle=(x+y)%3?'#d1d9d9':'#bdc8ca';c.fillRect(x+2,y+2,60,44);c.fillStyle='#e2e8e7';c.fillRect(x+3,y+3,58,2);}});stone.wrapS=stone.wrapT=T.RepeatWrapping;for(const [w,d,x,z]of[[7,37,0,-1],[31,6,0,-5]]){const tx=stone.clone();tx.repeat.set(w/6,d/5);const m=box(hub,w,.07,d,0xffffff,x,.015,z);m.material=new T.MeshStandardMaterial({map:tx,roughness:1});}
 for(let i=0;i<9;i++){const x=(i-4)*5.4,h=5+i%3;box(hub,5.7,h,6,0xa47451,x,h/2-1,-28,.15);box(hub,5.9,.6,6.1,0x73d24b,x,h-1,-28,.1);}
 for(const x of[-16,16])for(const z of[-19,-9,4]){box(hub,.6,3,.6,0x8c674c,x,1.3,z);box(hub,3.5,2.9,3.4,0x71c84e,x,3.6,z,.55);box(hub,2.9,2.2,2.9,0x91df62,x+.25,4.9,z,.45);}
 box(hub,13,.08,6.5,0xf9d85c,0,.045,17);for(let x=-6;x<=6;x++)for(let j=0;j<2;j++)box(hub,.96,.018,.48,(x+j)%2?0x25343b:0xffffff,x,.10,14.5+j*.48);
 for(const x of[-6.4,6.4]){box(hub,.18,2,.18,0xffffff,x,1,16);box(hub,1.1,.65,.05,0xff8264,x+(x>0?-.5:.5),1.6,16);}
 label(hub,'走进来，直接飞！',0,3.1,16,7);label(hub,'吃得越多，身体越圆',-10,3.5,-5,6);
 // A single snack stand makes the loop legible without a second activity or map.
 box(hub,3.4,1.1,2.2,0xf2b75e,-10,.55,-5,.15);box(hub,3.8,.18,2.6,0xfff1c8,-10,1.15,-5,.10);for(const x of[-11.3,-8.7])box(hub,.10,2.8,.10,0xffefce,x,1.4,-5.7);box(hub,4.1,.20,2.8,0xf39b66,-10,2.8,-5,.1);
 const course=new T.Group();scene.add(course);const colors=[0xf36e82,0xf2bd65,0xe9ec75,0x80dc62,0x6bd4c9,0x77b5e7,0xa39cda,0xe990c5],bands=[];
 for(let i=0;i<36;i++){const m=box(course,25,.10,22,colors[i%8],0,-.04,31+i*22);m.material=new T.MeshBasicMaterial({color:colors[i%8],toneMapped:false});const sign=label(course,'',0,.12,m.position.z+4,6);const old=sign.material.map;sign.removeFromParent();old.dispose();sign.material.dispose();const tx=texture(()=>{},512,128),mark=new T.Mesh(new T.PlaneGeometry(6,1.5),new T.MeshBasicMaterial({map:tx,transparent:true,depthWrite:false}));mark.rotation.set(-Math.PI/2,0,Math.PI);mark.position.set(0,.025,m.position.z+4);course.add(mark);bands.push({m,mark,tx,text:''});}
 return{update(z,distance,travel){const start=Math.max(0,Math.floor((z-20)/22)-4);bands.forEach((b,i)=>{const band=start+i;b.m.position.z=31+band*22;b.m.material.color.setHex(colors[band%8]);b.mark.position.z=b.m.position.z+4;const d=Math.max(0,Math.round((b.mark.position.z-18)/travel*distance)),text=d>=1000?(d/1000).toFixed(1)+'K':String(d);if(text!==b.text){const c=b.tx.image.getContext('2d');c.clearRect(0,0,512,128);c.fillStyle='#ffffff';c.font='900 90px Arial';c.textAlign='center';c.textBaseline='middle';c.fillText(text+' m',256,64);b.tx.needsUpdate=true;b.text=text;}});}};
}
